import {ACTIVE_GEMS,SUPPORT_GEMS,compatible,compileSkill,GEM_PRESETS} from './gems.js';
import {BESTIARY} from './monsters.js';
const tagNames={spell:'法術',projectile:'投射物',area:'範圍',hit:'命中',chain:'連鎖',duration:'持續'};
export function buildPanel(game,modal,close){
 const used=id=>game.links.findIndex(row=>row.supports.includes(id));
 const render=(message='')=>{
 const scroll=document.querySelector('.build-panel')?.scrollTop||0;
 modal(`<div class="build-panel"><div class="build-heading"><div><span class="eyebrow">GEM LINKS / 自由搭配</span><h2>技能工坊</h2></div><button class="secondary" id="closeBuild">完成配置 ↗</button></div><p class="build-intro">三組技能同時自動施放。每組可連接三顆相容輔助寶石；每顆寶石只能裝在一處，卸下不會消失。</p><div class="preset-bar"><span>快速配裝</span>${Object.entries(GEM_PRESETS).map(([id,p])=>`<button class="secondary" data-preset="${id}">${p.name}</button>`).join('')}</div><div class="build-notice" role="status">${message||'所有主動與輔助寶石開局即可使用。升級會精煉傷害或強化角色。'}</div><div class="link-grid">${game.links.map((row,i)=>{
 const a=ACTIVE_GEMS[row.active],stats=compileSkill(row,game.player,game.gemLevels);
 return `<section class="link-card" style="--gem-color:${a.color}"><div class="link-number">技能組 0${i+1}<span>${row.supports.filter(Boolean).length+1} 連線</span></div><label class="active-select"><span class="gem-symbol">${a.icon}</span><select data-active="${i}" aria-label="技能組 ${i+1} 的主動技能">${Object.entries(ACTIVE_GEMS).map(([id,g])=>`<option value="${id}" ${id===row.active?'selected':''} ${game.links.some((l,j)=>j!==i&&l.active===id)?'disabled':''}>${g.name}${game.links.some((l,j)=>j!==i&&l.active===id)?'（已裝備）':''}</option>`).join('')}</select></label><div class="gem-tags">${a.tags.map(t=>`<span>${tagNames[t]}</span>`).join('')}</div><p class="active-description">${a.desc}</p><div class="support-links">${row.supports.map((id,j)=>`<div class="support-socket"><span class="socket-dot">${id?SUPPORT_GEMS[id].icon:'＋'}</span><div><label for="support-${i}-${j}">輔助 ${j+1}</label><select id="support-${i}-${j}" data-row="${i}" data-socket="${j}"><option value="">空插槽</option>${Object.entries(SUPPORT_GEMS).map(([sid,g])=>{const fits=compatible(row.active,sid),owner=used(sid),occupied=owner>=0&&id!==sid;return `<option value="${sid}" ${id===sid?'selected':''} ${!fits||occupied?'disabled':''}>${g.name}${!fits?' · 不相容':occupied?` · 已裝於 ${owner+1} 組`:''}</option>`}).join('')}</select><small>${id?SUPPORT_GEMS[id].desc:'選擇輔助寶石來改變技能效果。'}</small></div></div>`).join('')}</div><div class="link-stats"><div><strong>${Math.round(stats.damage)}</strong><span>每次命中傷害</span></div><div><strong>${stats.rate.toFixed(2)}/s</strong><span>施放頻率${stats.echo?' ＋迴響':''}</span></div></div><div class="link-properties">${[stats.count>1?`${stats.count} 枚投射物`:'',stats.pierce?`穿透 ${stats.pierce}`:'',stats.chain?`連鎖 ${stats.chain}`:'',stats.fork?'命中分裂':'',stats.burn?'持續點燃':'',stats.leech?'生命偷取':'',stats.execute?'10% 撲殺':''].filter(Boolean).join(' · ')||'依照主動技能本身的效果施放'}</div></section>`}).join('')}</div><details class="build-codex"><summary>敵人與 Boss 圖鑑 · 8 種敵人 / 3 位 Boss</summary><div class="codex-grid">${BESTIARY.map(([n,d])=>`<div><strong>${n}</strong><p>${d}</p></div>`).join('')}</div></details><p class="build-footnote">輔助效果只影響所連接的技能。傷害欄為單次命中，尚未計入爆炸、燃燒、連鎖衰減與迴響。</p></div>`);
 document.querySelector('.build-panel').scrollTop=scroll;
 document.getElementById('closeBuild').onclick=close;
 document.querySelectorAll('[data-active]').forEach(el=>el.onchange=()=>{const result=game.configure(Number(el.dataset.active),'active',0,el.value);render(result.ok?'主動技能已替換；不相容的輔助寶石已卸下。':result.reason)});
 document.querySelectorAll('[data-socket]').forEach(el=>el.onchange=()=>{const result=game.configure(Number(el.dataset.row),'support',Number(el.dataset.socket),el.value||null);render(result.ok?'連線已更新，下次施放立即套用。':result.reason)});
 document.querySelectorAll('[data-preset]').forEach(el=>el.onclick=()=>{game.preset(el.dataset.preset);render(`已套用「${GEM_PRESETS[el.dataset.preset].name}」，仍可自由更換每個插槽。`)});
 };render();
}
